rds.\"\n    }\n  ],\n  \"entry_points\": [\n    {\n      \"identifier\": \"minisvc.cli:main\",\n      \"kind\": \"console_script\",\n      \"source\": \"pyproject.toml [project.scripts]\"\n    },\n    {\n      \"identifier\": \"minisvc.api.routes:register_routes\",\n      \"kind\": \"API registration\",\n      \"source\": \"minisvc/api/routes.py\"\n    },\n    {\n      \"identifier\": \"POST /orders\",\n      \"kind\": \"HTTP API\",\n      \"handler\": \"minisvc.api.handlers:create_order\"\n    },\n    {\n      \"identifier\": \"GET /orders/<order_id>\",\n      \"kind\": \"HTTP API\",\n      \"handler\": \"minisvc.api.handlers:get_order\"\n    }\n  ],\n  \"dependency_edges\": [\n    {\"from\": \"minisvc.cli\", \"to\": \"minisvc.config\", \"type\": \"imports\"},\n    {\"from\": \"minisvc.cli\", \"to\": \"minisvc.storage.repo\", \"type\": \"imports\"},\n    {\"from\": \"minisvc.storage.repo\", \"to\": \"minisvc.models\", \"type\": \"imports\"},\n    {\"from\": \"minisvc.api.routes\", \"to\": \"minisvc.api.handlers\", \"type\": \"imports\"},\n    {\"from\": \"minisvc.api.handlers\", \"to\": \"minisvc.audit\", \"type\": \"imports\"},\n    {\"from\": \"minisvc.api.handlers\", \"to\": \"minisvc.models\", \"type\": \"imports\"},\n    {\"from\": \"minisvc.api.handlers\", \"to\": \"minisvc.storage.repo\", \"type\": \"imports\"},\n    {\"from\": \"minisvc.cli:main\", \"to\": \"minisvc.config:load_settings\", \"type\": \"calls\"},\n    {\"from\": \"minisvc.cli:main\", \"to\": \"minisvc.storage.repo:OrderRepository\", \"type\": \"instantiates\"},\n    {\"from\": \"minisvc.cli:main\", \"to\": \"minisvc.storage.repo:OrderRepository.init_schema\", \"type\": \"calls\"},\n    {\"from\": \"minisvc.config:load_settings\", \"to\": \"MINISVC_DB and MINISVC_READONLY\", \"type\": \"reads_config\"},\n    {\"from\": \"minisvc.api.routes:register_routes\", \"to\": \"minisvc.api.handlers:create_order\", \"type\": \"calls\"},\n    {\"from\": \"minisvc.api.routes:register_routes\", \"to\": \"mi